const body = $json.body || $json;
return { json: {
  name: (body.name || body.full_name || '').trim(),
  email: (body.email || '').trim().toLowerCase(),
  phone: (body.phone || '').trim(),
  practice_area: (body.practice_area || '').trim(),
  case_description: (body.case_description || body.message || body.details || '').trim(),
  received_at: new Date().toISOString(),
} };

// A non-consumer email domain is a reasonable, free signal that a lead is inquiring on behalf of
// (or works for) a company -- not proof, just a useful heuristic to decide whether an enrichment
// lookup is worth attempting.
const lead = $json;
const consumerDomains = ($vars.CONSUMER_EMAIL_DOMAINS || 'gmail.com,yahoo.com,hotmail.com,outlook.com,aol.com,icloud.com,live.com').split(',').map(s => s.trim().toLowerCase());
const domain = lead.email.includes('@') ? lead.email.split('@')[1] : '';
const isBusinessDomain = !!domain && !consumerDomains.includes(domain);
return { json: { ...lead, email_domain: domain, is_business_domain: isBusinessDomain } };

// Provider response shapes vary widely -- this reads a generic {name, domain, industry,
// employeeCount} shape and falls back gracefully if the real provider's fields differ or the
// lookup found nothing, rather than crashing the whole briefing over a missing company match.
const lead = $('Extract Company Domain From Email').first().json;
const d = $json || {};
const companyName = d.name || d.company || d.organization || lead.email_domain;
const industry = d.industry || d.category || '';
const employeeCount = d.employeeCount || d.employee_count || d.metrics?.employees || null;
const found = !!(d.name || d.company || d.organization);
return { json: { ...lead, company_name: companyName, company_industry: industry, company_employee_count: employeeCount, company_data_found: found } };

// A rough keyword-based sorting signal, not a valuation -- never a legal or financial assessment
// of what the matter is actually worth.
const lead = $json;
const highValueKeywords = ($vars.HIGH_VALUE_KEYWORDS || 'wrongful death,class action,commercial litigation,catastrophic injury,multi-million').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const descLower = lead.case_description.toLowerCase();
const hasHighValueSignal = highValueKeywords.some(k => descLower.includes(k));
const hasDollarAmount = /\$[\d,]+/.test(lead.case_description);
let valueTier;
if (hasHighValueSignal || hasDollarAmount) valueTier = 'High';
else if (lead.company_data_found) valueTier = 'Medium';
else valueTier = 'Low';
return { json: { ...lead, matter_value_tier: valueTier, has_high_value_signal: hasHighValueSignal } };

const lead = $json;
const companyLine = lead.company_data_found
  ? `${lead.company_name}${lead.company_industry ? ' (' + lead.company_industry + ')' : ''}${lead.company_employee_count ? ', ~' + lead.company_employee_count + ' employees' : ''}`
  : (lead.is_business_domain ? `${lead.email_domain} (no enrichment match found)` : 'Personal email domain, no company signal');
const message = `New lead: ${lead.name}

Company: ${companyLine}
Matter value signal: ${lead.matter_value_tier}
Practice area: ${lead.practice_area}
Phone: ${lead.phone}
Email: ${lead.email}

${lead.case_description}

This briefing is a research head start, not a valuation -- review before treating the value signal as anything more than a sorting hint.`;
return { json: { ...lead, recipient: $vars.INTAKE_ATTORNEY_EMAIL || $vars.FIRM_EMAIL, subject: `New lead briefing: ${lead.name} (${lead.matter_value_tier} signal)`, message } };
